CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE promise_state AS ENUM ('proposed','accepted','active','proof_pending','verified','completed','declined','expired','ended_unverified','cancelled_by_admin');
CREATE TYPE back_state AS ENUM ('proposed','committed','active','payable','released','declined','cancelled','expired','returned','payment_failed');
CREATE TYPE visibility AS ENUM ('private','circle','public');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text, phone text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz, CHECK (email IS NOT NULL OR phone IS NOT NULL));
CREATE UNIQUE INDEX users_email_unique ON users (lower(email)) WHERE email IS NOT NULL;
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id), first_name text NOT NULL, last_name text, display_name text NOT NULL, avatar_url text, bio text, slug text UNIQUE, locale text NOT NULL DEFAULT 'en', timezone text NOT NULL DEFAULT 'UTC', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE promises (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), achiever_user_id uuid NOT NULL REFERENCES users(id), created_by_user_id uuid REFERENCES users(id), title text NOT NULL, category text NOT NULL, template_key text, description text, target_type text, target_value numeric, target_unit text, deadline timestamptz NOT NULL, success_criteria text NOT NULL, verification_method text NOT NULL, visibility visibility NOT NULL DEFAULT 'circle', state promise_state NOT NULL DEFAULT 'proposed', slug text NOT NULL UNIQUE, hero_image_url text, accepted_at timestamptz, activated_at timestamptz, proof_submitted_at timestamptz, verified_at timestamptz, completed_at timestamptz, ended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), promise_id uuid REFERENCES promises(id), backer_user_id uuid REFERENCES users(id), backer_name text NOT NULL, achiever_user_id uuid REFERENCES users(id), amount_minor integer NOT NULL CHECK(amount_minor > 0), currency char(3) NOT NULL DEFAULT 'USD', state back_state NOT NULL DEFAULT 'proposed', message text CHECK(length(message)<=280), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backing_commitments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), back_id uuid NOT NULL UNIQUE REFERENCES backs(id), provider text NOT NULL, provider_customer_ref text, provider_payment_method_ref text, commitment_state text NOT NULL, authorized_at timestamptz, payable_at timestamptz, released_at timestamptz, expired_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), back_id uuid NOT NULL REFERENCES backs(id), type text NOT NULL, provider text NOT NULL, provider_event_id text, amount_minor integer, currency char(3), payload_json jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX payment_events_provider_event_unique ON payment_events(provider,provider_event_id) WHERE provider_event_id IS NOT NULL;
CREATE TABLE progress_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), promise_id uuid NOT NULL REFERENCES promises(id), author_user_id uuid NOT NULL REFERENCES users(id), title text, body text, media_url text, activity_distance_m integer, activity_duration_s integer, activity_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE proof_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), promise_id uuid NOT NULL REFERENCES promises(id), submitted_by uuid NOT NULL REFERENCES users(id), note text, proof_url text, result_url text, state text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proof_submission_id uuid NOT NULL REFERENCES proof_submissions(id), reviewer_user_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX promises_achiever_state_idx ON promises(achiever_user_id,state); CREATE INDEX backs_promise_state_idx ON backs(promise_id,state); CREATE INDEX progress_promise_created_idx ON progress_updates(promise_id,created_at DESC);
